// Keep client source literal so Worker bundling cannot inject server-only helpers.
const appClientScript = String.raw`(function appClient({language, icons}) {
  const t=(zh,en)=>language==='en'?en:zh;
  const $=id=>document.getElementById(id);
  const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const icon=(name,cls='')=>'<svg class="'+cls+'" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+(icons[name]||icons.moon)+'</svg>';
  const money=n=>Number(n||0).toLocaleString(language==='en'?'en-US':'zh-CN');
  const yuan=fen=>'¥'+(Number(fen||0)/100).toFixed(2);
  const duration=n=>t(Math.floor(n/60)+' 小时 '+n%60+' 分钟',Math.floor(n/60)+' h '+n%60+' min');
  const date=v=>new Date(v).toLocaleString(language==='en'?'en-GB':'zh-CN',{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'});
  const day=v=>v?new Date(v+'T12:00:00Z').toLocaleDateString(language==='en'?'en-GB':'zh-CN',{year:'numeric',month:'short',day:'numeric'}):t('授权单夜样例','Shared single-night sample');
  const productNames={'sleep-mask':t('遮光睡眠眼罩','Blackout sleep mask'),'white-noise':t('白噪音七天权益','7 days of white noise'),'pillow-coupon':t('睡眠枕商城优惠券','Sleep pillow voucher')};
  const productDescriptions={'sleep-mask':t('柔软遮光，留一段安静给自己','A little darkness. A little more rest.'),'white-noise':t('为睡前准备一片安静的声音','A quieter soundtrack for bedtime.'),'pillow-coupon':t('把好梦积攒成一份舒适','Put your points toward comfort.')};
  const originalNames={'遮光睡眠眼罩':'sleep-mask','白噪音七天权益':'white-noise','睡眠枕商城优惠券':'pillow-coupon'};
  const title=p=>productNames[p.productId||originalNames[p.title]||p.id]||esc(p.title);
  const art=id=>'<div class="product-art '+(id==='white-noise'?'sound':id==='pillow-coupon'?'pillow':'mask')+'">'+icon(id==='white-noise'?'sound':id==='pillow-coupon'?'pillow':'mask')+'</div>';
  const viewNames={today:t('今日','Today'),sleep:t('睡眠','Sleep'),rewards:t('权益','Rewards'),me:t('我的','Me')};
  let state=null,busy=false,unresolvedOrder=null,unresolvedToken=null,rewardsView='shop',toastTimer,lastSynced=null;
  let storage=null;
  for(const kind of ['localStorage','sessionStorage']){try{const candidate=window[kind];candidate.setItem('momo-storage-test','1');candidate.removeItem('momo-storage-test');storage=candidate;break;}catch{}}
  const read=key=>{try{return storage?.getItem(key);}catch{return null;}};
  const save=(key,value)=>{try{if(value==null)storage?.removeItem(key);else storage?.setItem(key,value);}catch{}};
  if(['shop','cash','token','orders'].includes(read('momoRewardsView')))rewardsView=read('momoRewardsView');
  const uuid=value=>/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(value||'');
  let accountId=read('sleepDemoAccount');
  if(!/^[A-Za-z0-9-]{8,80}$/.test(accountId||''))accountId=crypto.randomUUID();
  save('sleepDemoAccount',accountId);
  let simulationId=read('momoSimulationId');if(!uuid(simulationId))simulationId=null;
  for(const kind of ['order','token']){try{const pending=JSON.parse(read(kind==='order'?'momoPendingOrder':'momoPendingToken')||'null');if(pending?.accountId===accountId&&uuid(pending.requestId)){if(kind==='order')unresolvedOrder=pending;else unresolvedToken=pending;}}catch{}}
  let goalMinutes=Number(read('momoSleepGoal'))||480;if(!Number.isInteger(goalMinutes)||goalMinutes<360||goalMinutes>600)goalMinutes=480;
  const sample=()=>simulationId&&state.simulationSleep?state.simulationSleep:state.sampleSleep;
  const report=()=>sample().scoreBreakdown;
  const received=()=>[state.currentClaim,state.currentSimulationClaim,...state.claims].find(c=>c?.nightKey===sample().nightKey);
  const route=()=>Object.hasOwn(viewNames,location.hash.slice(1))?location.hash.slice(1):'today';
  const arrow=()=>icon('arrow','arrow');
  const synthetic=()=>sample().source==='synthetic';
  const sampleTag=()=>'<span class="tag">'+t(synthetic()?'模拟数据':'授权样例 A',synthetic()?'Simulated data':'Shared sample A')+'</span>';
  const empty=(image,name,message,button='')=>'<div class="empty">'+icon(image)+'<h3>'+name+'</h3><p>'+message+'</p>'+button+'</div>';
  const heading=(name,subtitle)=>'<div class="page-title"><div><p class="eyebrow">'+subtitle+'</p><h1 tabindex="-1">'+name+'</h1><p class="sync-time">'+(lastSynced?t('上次刷新 ','Last refreshed ')+esc(date(lastSynced)):t('正在同步','Syncing'))+'</p></div>'+sampleTag()+'</div>';
  const sourceNote=()=>'<p class="source-note">'+icon('ring')+t(synthetic()?'人物与夜晚均为模拟，设备未连接。':'授权公开的单夜样例，设备未连接。',synthetic()?'Fictional person and night. No device connected.':'Shared single-night sample. No device connected.')+'</p>';
  const claimButton=()=>'<button id="claim" class="primary '+(received()?'claimed':'')+'" '+(received()||busy?'disabled':'')+'>'+icon(received()?'check':'gift')+(received()?t('积分已领取','Points claimed'):t('领取本晚 ','Claim this night’s ')+money(report().awardedPoints)+t(' 积分',' points'))+'</button>';
  const personName=s=>s.person?t(s.person.nameZh,s.person.nameEn):t('样例 A','Sample A');
  const personRole=s=>s.person?t(s.person.roleZh,s.person.roleEn):t('用户授权公开','Shared with permission');
  function selector(){const s=sample();return '<section class="night-selector" aria-label="'+t('当前睡眠记录','Current sleep record')+'"><div class="persona"><div class="persona-avatar" aria-hidden="true">'+esc(personName(s).slice(0,1))+'</div><div><h2>'+esc(personName(s))+' <small>'+t(synthetic()?'虚拟人物':'单夜样例',synthetic()?'Fictional person':'One-night sample')+'</small></h2><p>'+esc(personRole(s))+' · '+esc(day(s.nightDate))+'</p></div></div><div class="sim-actions"><button class="random-button" data-action="random">'+icon('refresh')+t('随机人物与夜晚','Random person & night')+'</button><button class="text-button" data-action="sample-a">'+t('样例 A','Sample A')+'</button></div></section>';}
  const stages=[['core',t('浅睡','Light'),'#9c8ac3'],['rem','REM','#cfbce8'],['deep',t('深睡','Deep'),'#71618f'],['awake',t('清醒','Awake'),'#deb6cb']];
  function stageBar(){const s=report(),total=s.visibleStageMinutes+s.unclassifiedWindowMinutes;return '<div class="stage-bar" role="img" aria-label="'+t('整晚睡眠阶段汇总，不是逐分钟时间线','Whole-night stage totals, not a minute-by-minute timeline')+'">'+stages.map(([key,,color])=>'<span style="width:'+s.sourceStageMinutes[key]/total*100+'%;background:'+color+'"></span>').join('')+'<span style="width:'+s.unclassifiedWindowMinutes/total*100+'%;background:#51485f"></span></div>';}
  function sleepCard(){const s=report();return '<section class="card sleep-card"><div class="card-top"><h2>'+t('这一晚，睡了多久','A night of rest')+'</h2><button class="text-button" data-action="goal">'+t('目标 ','Goal ')+duration(goalMinutes)+'</button></div><div class="sleep-amount">'+Math.floor(s.sourceMinutes/60)+'<small>'+t('小时','h')+'</small>'+s.sourceMinutes%60+'<small>'+t('分钟','min')+'</small></div><div class="sleep-window">'+icon('moon')+esc(sample().windowLabel)+'</div>'+stageBar()+'<p class="stage-caption">'+t('浅睡、REM、深睡与清醒的整晚构成','Light, REM, deep and awake: whole-night composition')+'</p><div class="sleep-footer"><div><strong>'+s.deepRatioPercent+'%</strong><small>'+t('深睡占比','Deep sleep ratio')+'</small></div><div><strong>'+s.interruptionCount+'</strong><small>'+t('中断次数','Interruptions')+'</small></div><div><strong>'+Math.round(s.continuityFactor*100)+'%</strong><small>'+t('连续性系数','Continuity factor')+'</small></div></div></section>';}
  function history(){const nights=state.claims.filter(c=>c.scoreBreakdown?.simulationId||c.nightKey==='disclosed-example-a');return nights.length?'<div class="history-grid">'+nights.map(c=>{const s=c.scoreBreakdown;return '<button class="night-history" data-night="'+esc(s?.simulationId||'sample-a')+'" aria-pressed="'+(c.nightKey===sample().nightKey)+'"><div><strong>'+esc(s?.person?t(s.person.nameZh,s.person.nameEn):t('授权样例 A','Shared sample A'))+'</strong><p>'+esc(day(s?.nightDate))+' · '+duration(s.sourceMinutes)+'</p></div><span>+'+money(c.awardedPoints)+'</span></button>';}).join('')+'</div>':empty('moon',t('从一晚开始','Start with one night'),t('随机生成睡眠记录，再领取积分。','Generate a sleep record, then claim its points.'));}
  function quickRewards(){return '<div class="quick-grid">'+[['shop','gift',t('换商品','Goods'),t('眼罩与睡眠权益','Sleep essentials')],['cash','wallet',t('换人民币','RMB'),t('试点报价与申请','Pilot quote & request')],['token','globe',t('换代币','Tokens'),t('虚拟 SLEEP 体验','Virtual SLEEP demo')]].map(([view,image,name,note])=>'<button class="quick-card" data-reward-route="'+view+'">'+icon(image)+'<div><strong>'+name+'</strong><p>'+note+'</p></div></button>').join('')+'</div>';}
  function today(){return heading(t('让每一晚都有记录','Every night, remembered'),t('睡眠、积分与好梦权益','Your sleep and rewards'))+selector()+'<div class="home-grid"><div>'+sleepCard()+sourceNote()+'</div><aside><section class="card reward-card"><div class="reward-head"><div class="reward-badge">'+icon('leaf')+'</div><div class="reward-info"><h3>'+t(received()?'本晚奖励已到账':'本晚可领取的奖励',received()?'This night’s reward is in':'Your reward for this night')+'</h3><p>'+t('按阶段、连续性与作息计分','Stages, continuity and schedule')+'</p></div></div><div class="points-number">+'+money(received()?.awardedPoints||report().awardedPoints)+'<small>'+t('沙盒积分','sandbox points')+'</small></div>'+claimButton()+'</section><div class="balance-inline"><span>'+t('当前可用积分','Available points')+'</span><strong id="today-balance">'+money(state.account.points)+'</strong></div>'+quickRewards()+'</aside><section class="wide"><div class="section-heading"><h2>'+t('最近领取的夜晚','Recently claimed nights')+'</h2><button class="text-button" data-action="ledger">'+t('积分明细','Points activity')+arrow()+'</button></div>'+history()+'<p class="fine-note">'+t('最近 20 晚。模拟人物共用当前体验账户，积分可用于沙盒兑换。','Latest 20 nights. Fictional people share this demo account; points can be used for sandbox redemptions.')+'</p></section></div>';}
  function sleep(){const s=report();return heading(t('这一晚的睡眠报告','This night’s sleep report'),esc(day(sample().nightDate)))+selector()+'<div class="home-grid"><div><section class="card"><div class="card-top"><h2>'+t('睡眠阶段构成','Sleep composition')+'</h2><span class="muted small">'+duration(s.sourceMinutes)+'</span></div>'+stageBar()+stages.map(([key,name,color])=>'<div class="stage-row"><i class="stage-dot" style="background:'+color+'"></i><span>'+name+'</span><strong>'+duration(s.sourceStageMinutes[key])+'</strong></div>').join('')+'<div class="stage-row"><i class="stage-dot" style="background:#51485f"></i><span>'+t('未分类','Unclassified')+'</span><strong>'+s.unclassifiedWindowMinutes+t(' 分钟',' min')+'</strong></div><p class="fine-note">'+t('阶段按整晚汇总展示；清醒与未分类时段不计入有效睡眠。','Whole-night totals. Awake and unclassified time are excluded from time asleep.')+'</p></section><div class="overview-stats"><div class="stat-card"><div class="label">'+t('有效睡眠','Time asleep')+'</div><div class="stat-value">'+s.sourceMinutes+'<small>'+t('分钟','min')+'</small></div></div><div class="stat-card"><div class="label">'+t('清醒时长','Time awake')+'</div><div class="stat-value">'+s.awakeMinutes+'<small>'+t('分钟','min')+'</small></div></div><div class="stat-card"><div class="label">'+t('中断次数','Interruptions')+'</div><div class="stat-value">'+s.interruptionCount+'<small>'+t('次','times')+'</small></div></div></div>'+sourceNote()+'</div><section class="card"><div class="card-top"><h2>'+t('这一晚如何计分','How this night earns points')+'</h2><span class="tag mint">V'+s.scoringVersion+'</span></div><div class="detail-row"><span>'+t('阶段积分','Stage points')+'</span><strong>'+s.stagePoints+'</strong></div><div class="detail-row"><span>'+t('连续性系数','Continuity factor')+'</span><strong>× '+s.continuityFactor+'</strong></div><div class="detail-row"><span>'+t('规律性系数','Schedule factor')+'</span><strong>× '+s.regularityFactor.toFixed(2)+'</strong></div><div class="formula">'+s.stagePoints+' × '+s.continuityFactor+' × '+s.regularityFactor.toFixed(2)+' ≈ '+s.awardedPoints+'<small>'+t('服务端按当前规则复算并四舍五入','Recomputed and rounded by the server')+'</small></div><details class="disclosure"><summary>'+t('查看计分依据','Scoring details')+'</summary><p>'+t('浅睡每分钟 1 分，REM 每分钟 2 分；深睡本晚权重 '+s.effectiveDeepWeight+' 分/分钟。','Light earns 1 point/min, REM earns 2, and this night’s deep-sleep weight is '+s.effectiveDeepWeight+' points/min.')+'</p><p>'+t(synthetic()?'此处全部数据由模拟器生成，作息偏差也为演示输入。':'样例 A 的 6 次中断为截图估计；规律性与演示目标 21:00–07:00 比较。',synthetic()?'All data and schedule deviations are generated by the simulator.':'Sample A uses six estimated interruptions and a demo schedule of 21:00–07:00.')+'</p><p>'+t('25% 深睡是激励参数，不是医学标准；积分不是睡眠质量诊断。','The 25% deep-sleep target is a reward parameter, not a medical standard. Points are not a sleep diagnosis.')+'</p></details>'+claimButton()+'</section></div>';}
  function orders(){return state.orders.length?'<div class="list-card">'+state.orders.map(o=>'<button class="list-row" data-order="'+esc(o.id)+'">'+icon('gift')+'<div class="row-copy"><strong>'+title(o)+'</strong><p>'+esc(date(o.createdAt))+' · '+t('体验兑换已完成','Demo redemption completed')+'</p></div><span class="row-value">−'+money(o.pricePoints)+'</span>'+arrow()+'</button>').join('')+'</div>':empty('gift',t('第一份权益，等你来兑换','Your first reward is waiting'),t('领取睡眠积分后，就能在这里兑换。','Claim sleep points, then choose a reward.'),'<button class="secondary" data-reward-route="shop">'+t('去看看商品','Explore goods')+'</button>');}
  const inputField=(id,name,max,value)=>'<label class="form-field" for="'+id+'"><span>'+name+'</span><input id="'+id+'" type="number" inputmode="numeric" min="1" max="'+max+'" step="1" value="'+value+'" required></label>';
  function cashView(){const p=state.cashPolicy,pending=state.cashRedemptions.find(r=>r.status==='integration_pending');return '<div class="conversion-grid"><section class="card"><h2 class="panel-title">'+icon('wallet')+t('积分兑换人民币','Points to RMB')+'</h2><p class="fine-note">'+t('当期试点报价：100 积分 = ','Current pilot quote: 100 points = ')+yuan(p.rateFenPer100Points)+'</p><form id="cash-form">'+inputField('cash-points',t('使用积分','Points to use'),Math.min(state.account.points,p.maximumPoints),Math.min(state.account.points,Math.max(p.minimumPoints,390)))+'<div class="preset-row"><button type="button" data-preset="cash" data-value="100">100</button><button type="button" data-preset="cash" data-value="390">390</button><button type="button" data-preset="cash" data-value="all">'+t('全部可用','Max available')+'</button></div><div class="amount-quote"><p>'+t('对应人民币金额','Quoted RMB amount')+'</p><strong id="cash-estimate">¥0.00</strong></div><p id="cash-limit" class="fine-note"></p><div class="status-note">'+t('兑付通道待接入。提交仅保存申请，不扣积分，也不打款。','Payout integration is pending. Submitting saves a request without spending points or sending money.')+'</div><button class="primary" id="cash-submit" type="submit" '+(pending?'disabled':'')+'>'+t(pending?'已有待接入申请':'保存兑付申请',pending?'A request is pending':'Save payout request')+'</button></form><p class="fine-note">'+t('资金来源：未来的品牌或数据买方预算；目前尚未到账。当前报价不代表已具备现金收益。','Funding is intended to come from brand or data-buyer budgets; none has been received. This quote is not a cash return.')+'</p></section><section class="history-panel"><h3>'+t('兑付申请记录','Payout requests')+'</h3>'+(state.cashRedemptions.length?state.cashRedemptions.map(r=>'<div class="entry"><div><strong>'+yuan(r.amountFen)+' · '+money(r.points)+t(' 积分',' points')+'</strong><small>'+t(r.status==='cancelled'?'已取消':'等待通道接入 · 未打款',r.status==='cancelled'?'Cancelled':'Integration pending · Unpaid')+'</small><small>'+esc(date(r.createdAt))+'</small></div>'+(r.status==='integration_pending'?'<button class="text-button" data-cancel-cash="'+esc(r.id)+'">'+t('取消申请','Cancel request')+'</button>':'')+'</div>').join(''):empty('wallet',t('还没有兑付申请','No payout requests'),t('先领取积分，再计算可兑换金额。','Claim points, then calculate your quote.')))+'</section></div>';}
  function tokenView(){const p=state.tokenExchangePolicy||{minimumPoints:1,maximumPoints:10000};return '<div class="conversion-grid"><section class="card"><h2 class="panel-title">'+icon('globe')+t('积分兑换虚拟 SLEEP','Points to virtual SLEEP')+'</h2><p class="fine-note">'+t('1 沙盒积分 = 1 虚拟 SLEEP','1 sandbox point = 1 virtual SLEEP')+'</p><div class="balance-inline"><span>'+t('虚拟代币余额','Virtual token balance')+'</span><strong id="token-balance">'+money(state.stats?.virtualTokenBalance)+' SLEEP</strong></div><form id="token-form">'+inputField('token-points',t('使用积分','Points to use'),Math.min(state.account.points,p.maximumPoints),unresolvedToken?.points||Math.min(state.account.points,100))+'<div class="preset-row"><button type="button" data-preset="token" data-value="100">100</button><button type="button" data-preset="token" data-value="390">390</button><button type="button" data-preset="token" data-value="all">'+t('全部可用','Max available')+'</button></div><div class="amount-quote"><p>'+t('预计获得','You receive')+'</p><strong id="token-estimate">0 SLEEP</strong></div><p id="token-limit" class="fine-note"></p><div class="status-note">'+t('这是兑换体验：扣减沙盒积分、增加虚拟余额并保存记录，不发送链上交易。','Demo exchange: spends sandbox points, credits virtual tokens and saves a record. No blockchain transaction is sent.')+'</div><button class="primary" id="token-submit" type="submit">'+t(unresolvedToken?'恢复这笔兑换':'确认兑换虚拟代币',unresolvedToken?'Resume this exchange':'Exchange for virtual tokens')+'</button></form></section><div><section class="history-panel"><h3>'+t('代币兑换记录','Token exchange history')+'</h3>'+(state.tokenExchanges?.length?state.tokenExchanges.map(r=>'<div class="entry"><div><strong>'+money(r.tokenAmount??r.points)+' SLEEP</strong><small>'+t('虚拟兑换完成','Virtual exchange completed')+' · '+esc(date(r.createdAt))+'</small><small>'+t('使用 ','Used ')+money(r.points)+t(' 积分',' points')+'</small></div><span class="tag">'+t('模拟','Demo')+'</span></div>').join(''):empty('globe',t('还没有代币兑换','No token exchanges yet'),t('余额只用于体验，不具有交易价值。','Virtual balances are for this demo and have no trading value.')))+'</section><section class="card spaced"><h3>'+t('真实 Monad 测试网验证','Live Monad Testnet verification')+'</h3><p class="fine-note">'+t('仅授权样例 A 可用于现有测试网铸币验证。随机生成的记录不具备资格；铸币根据凭证，不扣减积分余额。测试代币无现金价值。','Only shared sample A is eligible for the existing testnet mint. Random records are excluded. Minting uses a receipt and does not spend the points balance. Test tokens have no cash value.')+'</p><button class="secondary spaced" data-action="chain">'+t('查看测试网凭证与入口','View testnet receipts & entry')+'</button></section></div></div>';}
  function rewards(){const earned=state.stats?.earnedPoints??0,spent=state.stats?.spentPoints??0;return heading(t('把积分用在好梦里','Rewards for your rest'),t('积分账户与兑换中心','Points and redemptions'))+'<section class="card balance-card"><div class="balance-caption">'+icon('wallet')+t('可用沙盒积分','Available sandbox points')+'</div><div class="balance-amount" id="rewards-balance">'+money(state.account.points)+'<small>'+t('积分','points')+'</small></div><div class="balance-footer"><span>'+t('与官网共用体验账户，刷新后保留','Shared with the website and saved after refresh')+'</span><button class="text-button" data-action="ledger">'+t('查看明细','View activity')+arrow()+'</button></div><div class="balance-summary"><span>'+t('累计获得','Total earned')+'<strong>'+money(earned)+'</strong></span><span>'+t('累计使用','Total spent')+'<strong>'+money(spent)+'</strong></span><span>'+t('虚拟 SLEEP','Virtual SLEEP')+'<strong>'+money(state.stats?.virtualTokenBalance)+'</strong></span></div></section><div class="segmented" aria-label="'+t('兑换方式','Redemption type')+'">'+[['shop',t('换商品','Goods')],['cash',t('换人民币','RMB')],['token',t('换代币','Tokens')],['orders',t('我的兑换','My redemptions')]].map(([v,label])=>'<button type="button" data-rewards="'+v+'" aria-pressed="'+(rewardsView===v)+'">'+label+'</button>').join('')+'</div>'+(rewardsView==='cash'?cashView():rewardsView==='token'?tokenView():rewardsView==='orders'?orders():'<p class="flow-note">'+icon('check')+t('领取积分后选择权益，兑换记录自动保存','Claim points, choose a reward, and keep a saved receipt')+'</p><div class="shop-grid">'+state.products.map(p=>'<button class="product" data-product="'+esc(p.id)+'">'+art(p.id)+'<div class="product-copy"><h3>'+title(p)+'</h3><p>'+productDescriptions[p.id]+'</p><div class="product-price">'+money(p.pricePoints)+'<small>'+t('积分','points')+'</small></div></div>'+arrow()+'</button>').join('')+'</div><p class="fine-note">'+t('体验商品：扣减沙盒积分并保存兑换记录，不配送实物。','Demo goods: uses sandbox points and saves a record. No physical delivery.')+'</p>');}
  function row(image,label,value,action){return '<button class="list-row" data-action="'+action+'">'+icon(image)+'<span class="row-copy">'+label+'</span><span class="row-value">'+value+'</span>'+arrow()+'</button>';}
  function me(){return '<div class="profile"><div class="avatar">'+icon('moon')+'</div><div><h1 tabindex="-1">'+t('我的 MOMO','My MOMO')+'</h1><p>'+t('匿名体验账户','Anonymous demo account')+' · '+esc(accountId.slice(0,8))+'</p></div></div><div class="profile-stats"><div><strong>'+money(state.account.points)+'</strong><span>'+t('可用积分','Available points')+'</span></div><div><strong>'+money(state.stats?.claimedNights)+'</strong><span>'+t('已领夜晚','Claimed nights')+'</span></div><div><strong>'+money(state.stats?.orderCount)+'</strong><span>'+t('商品兑换','Goods redeemed')+'</span></div></div><div class="list-card">'+row('ring',t('设备与数据来源','Device & data source'),t('设备未连接','Not connected'),'source')+row('moon',t('睡眠目标','Sleep goal'),duration(goalMinutes),'goal')+row('wallet',t('积分明细','Points activity'),'','ledger')+row('gift',t('我的商品兑换','My goods redemptions'),'','orders')+row('document',t('睡眠与测试网凭证','Sleep & testnet receipts'),'','receipts')+'</div><div class="list-card spaced">'+row('globe',t('语言 / Language','Language / 语言'),language==='en'?'English':'简体中文','language')+row('document',t('账户与隐私','Account & privacy'),'','privacy')+'</div><div class="footer-links"><a href="/?lang='+language+'">'+t('返回官网','MOMO website')+'</a><button data-action="restart">'+t('重新体验','Start fresh')+'</button></div><p class="version">MOMO Sleep · Web App 1.1</p>';}
  function render(){if(!state)return;if(route()==='rewards')save('momoRewardsView',rewardsView);$('content').innerHTML=({today,sleep,rewards,me})[route()]();$('content').setAttribute('aria-busy','false');document.querySelectorAll('[data-tab]').forEach(a=>{if(a.dataset.tab===route())a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});updateBusy();updateQuotes();}
  function updateBusy(){$('refresh').disabled=busy;document.querySelectorAll('[data-submit],#claim,[data-action="random"],[data-action="sample-a"],[data-night],[data-cancel-cash]').forEach(b=>{b.disabled=busy||(b.id==='claim'&&!!state&&!!received())||b.dataset.unavailable==='true';});if($('cash-submit'))$('cash-submit').disabled=busy||!!state.cashRedemptions.find(r=>r.status==='integration_pending');if($('token-submit'))$('token-submit').disabled=busy;updateQuotes();}
  function toast(message){clearTimeout(toastTimer);$('toast').textContent=message;$('toast').hidden=false;toastTimer=setTimeout(()=>{$('toast').hidden=true;},5500);}
  function connection(ok){$('connection').className='connection'+(ok?'':' offline');$('connection').innerHTML='<i></i>'+(ok?t('已同步','Synced'):t('未连接','Offline'));}
  function errorBanner(message){const box=$('connection-error');box.hidden=!message;box.replaceChildren();if(message){box.append(document.createTextNode(message));const retry=document.createElement('button');retry.type='button';retry.textContent=t('重新连接','Reconnect');retry.onclick=()=>refresh();box.append(retry);if(unresolvedOrder||unresolvedToken){const recover=document.createElement('button');recover.type='button';recover.textContent=t('恢复待确认兑换','Resume pending redemption');recover.onclick=()=>{if(unresolvedOrder)redeemSheet(unresolvedOrder.productId);else{rewardsView='token';go('rewards');}};box.append(recover);}}}
  function savePendingOrder(order){unresolvedOrder=order;save('momoPendingOrder',order?JSON.stringify(order):null);}
  function savePendingToken(order){unresolvedToken=order;save('momoPendingToken',order?JSON.stringify(order):null);}
  function reconcilePending(){if(unresolvedOrder&&state.orders.some(r=>r.id===unresolvedOrder.requestId))savePendingOrder(null);if(unresolvedToken&&state.tokenExchanges?.some(r=>r.id===unresolvedToken.requestId))savePendingToken(null);if(unresolvedOrder||unresolvedToken)errorBanner(t('上一笔兑换尚待确认，请在对应兑换页恢复同一笔请求，避免重复扣分。','A redemption is awaiting confirmation. Resume the same request on its redemption page to avoid another charge.'));}
  const stateURL=()=>'/api/demo/state?accountId='+encodeURIComponent(accountId)+(simulationId?'&simulationId='+encodeURIComponent(simulationId):'');
  async function api(path,body){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),15000);try{const response=await fetch(path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify({accountId,simulationId,...body}):undefined,signal:controller.signal,cache:'no-store'});const data=await response.json();if(!response.ok){const e=new Error(data.error||t('请求失败','Request failed'));e.status=response.status;throw e;}if(!data.account||!data.sampleSleep?.scoreBreakdown||!Array.isArray(data.orders)||(simulationId&&data.simulationSleep?.simulationId!==simulationId))throw new Error(t('服务正在更新，请稍后刷新','Service is updating. Refresh shortly.'));return data;}finally{clearTimeout(timer);}}
  function errorMessage(e){const messages={'沙盒积分不足':'Not enough sandbox points','当前积分不足':'Not enough points','这个模拟夜晚已经领取过积分':'Points for this night have already been claimed','商品不存在或已售罄':'This reward is unavailable','已有一笔待接入兑付申请，请先完成或取消':'A payout request is pending. Cancel it first.','兑换请求编号已被使用':'This request ID is already in use','请输入有效的 EVM 钱包地址':'Enter a valid EVM wallet address','测试网铸币暂未开放':'Testnet minting is temporarily unavailable','请先计算并领取样例 A 的睡眠积分':'Claim shared sample A first','兑换积分必须是整数':'Points must be a whole number','兑换积分必须为 1–10000 的整数':'Use a whole number from 1 to 10000','未找到本账户的兑付申请':'This account has no matching payout request','此兑付申请不能取消':'This payout request cannot be cancelled'};return e.name==='AbortError'?t('连接超时，请刷新核对记录后再试','Timed out. Refresh to check your records before retrying.'):e instanceof TypeError?t('网络连接失败，请重新连接','Unable to connect. Please reconnect.'):language==='en'?messages[e.message]||(/最低兑换 (\d+) 积分/.test(e.message)?'Minimum '+e.message.match(/\d+/)[0]+' points':/单次最多兑换 (\d+) 积分/.test(e.message)?'Maximum '+e.message.match(/\d+/)[0]+' points per request':/[\u3400-\u9fff]/.test(e.message)?'Unable to complete this request. Refresh your records and retry.':e.message):e.message;}
  async function refresh(nextId=simulationId){if(busy)return;const previous=simulationId;busy=true;updateBusy();simulationId=nextId;try{const data=await api(stateURL());state=data;save('momoSimulationId',simulationId);lastSynced=new Date().toISOString();connection(true);errorBanner('');reconcilePending();render();}catch(e){simulationId=previous;connection(false);errorBanner(errorMessage(e));if(!state)$('content').innerHTML=empty('moon',t('暂时无法读取账户','Could not load your account'),t('请检查网络，再点击上方刷新。','Check your connection, then refresh above.'));$('content').setAttribute('aria-busy','false');}finally{busy=false;updateBusy();updateQuotes();}}
  function openSheet(name,content){$('sheet-content').innerHTML='<div class="sheet-heading"><h2>'+name+'</h2><button class="icon-button" data-action="close" aria-label="'+t('关闭','Close')+'">'+icon('close')+'</button></div>'+content;if(!$('sheet').open)$('sheet').showModal();updateBusy();}
  function go(view){$('sheet').close();if(location.hash==='#'+view)render();else location.hash=view;}
  function redeemSheet(id){const product=state.products.find(p=>p.id===id);if(!product)return;const otherPending=unresolvedOrder&&unresolvedOrder.productId!==id,resuming=unresolvedOrder?.productId===id,available=!otherPending&&(resuming||Number(product.stock)>0&&state.account.points>=product.pricePoints);openSheet(t('兑换商品','Redeem goods'),art(id)+'<h3 class="product-title">'+title(product)+'</h3><p class="product-description">'+productDescriptions[id]+'</p><div class="detail-row"><span>'+t('本次使用','Cost')+'</span><strong>'+money(product.pricePoints)+t(' 积分',' points')+'</strong></div><div class="detail-row"><span>'+t('可用积分','Available')+'</span><strong>'+money(state.account.points)+'</strong></div>'+(available&&!resuming?'<div class="detail-row"><span>'+t('兑换后剩余','Balance after')+'</span><strong>'+money(state.account.points-product.pricePoints)+'</strong></div>':'')+'<button data-submit="order" data-id="'+esc(id)+'" data-unavailable="'+!available+'" class="primary">'+(otherPending?t('请先确认上一笔兑换','Resolve your pending redemption first'):resuming?t('恢复这笔兑换','Resume this redemption'):available?t('确认兑换','Confirm redemption'):Number(product.stock)<=0?t('暂时售罄','Unavailable'):t('还差 ','Need ')+money(product.pricePoints-state.account.points)+t(' 积分',' more points'))+'</button><p class="fine-note">'+t('体验兑换扣减沙盒积分、保存记录，不配送实物。重试沿用同一请求编号。','Demo redemption spends sandbox points and saves a record. No physical delivery. Retries use the same request ID.')+'</p>');}
  function orderSheet(o,success=false){openSheet(success?t('兑换成功','Redemption complete'):t('兑换详情','Redemption details'),(success?'<div class="big-success">'+icon('check')+'</div>':'')+'<h3 class="product-title">'+title(o)+'</h3><p class="product-description">'+t('体验兑换已完成','Demo redemption completed')+'</p><div class="detail-row"><span>'+t('使用积分','Points used')+'</span><strong>−'+money(o.pricePoints)+'</strong></div><div class="detail-row"><span>'+t('当前余额','Current balance')+'</span><strong>'+money(state.account.points)+'</strong></div><div class="detail-row"><span>'+t('兑换时间','Redeemed at')+'</span><strong>'+esc(date(o.createdAt))+'</strong></div><div class="receipt-id">'+esc(o.id)+'</div><p class="fine-note">'+t('记录已保存，无实物配送。','Record saved. No physical delivery.')+'</p><button class="primary" data-action="orders">'+t('查看我的兑换','View my redemptions')+'</button>');}
  function ledger(){const labels={sleep_reward:t('睡眠奖励','Sleep reward'),shop_purchase:t('商品兑换','Goods redemption'),virtual_token_exchange:t('虚拟代币兑换','Virtual token exchange')};openSheet(t('积分明细','Points activity'),state.entries.length?state.entries.map(e=>'<div class="entry"><div><strong>'+(labels[e.kind]||t('积分变动','Points change'))+'</strong><small>'+esc(date(e.createdAt))+'</small></div><span class="amount '+(e.points<0?'negative':'')+'">'+(e.points>0?'+':'−')+money(Math.abs(e.points))+'</span></div>').join('')+'<p class="fine-note">'+t('显示最近 30 笔，累计金额见积分账户。','Latest 30 entries. See your points account for lifetime totals.')+'</p>':empty('wallet',t('还没有积分记录','No activity yet'),t('领取本晚积分即可开始。','Claim this night’s points to start.')));}
  function receipts(){const claims=state.claims.map(c=>'<div class="entry"><div><strong>'+t(c.status==='simulated'?'模拟夜晚凭证':'授权样例凭证',c.status==='simulated'?'Simulated-night receipt':'Shared-sample receipt')+'</strong><small>'+esc(date(c.createdAt))+' · +'+money(c.awardedPoints)+'</small></div><span class="tag">'+t('沙盒','Sandbox')+'</span></div><div class="receipt-id">'+esc(c.id)+'</div>');const live=state.tokenMints.filter(m=>m.status==='confirmed'&&/^0x[0-9a-f]{64}$/i.test(m.transactionHash||'')).map(m=>'<a class="receipt-link" target="_blank" rel="noopener noreferrer" href="https://testnet.monadscan.com/tx/'+m.transactionHash+'">'+t('查看 Monad 测试网凭证','View Monad Testnet receipt')+' ↗</a>');openSheet(t('我的凭证','My receipts'),(claims.length?claims.join(''):empty('document',t('还没有睡眠凭证','No sleep receipts yet'),t('领取积分后生成唯一记录。','Claim points to create a unique record.')))+'<p class="fine-note">'+t('沙盒记录与实际链上交易分开，模拟记录不代表真实上链。','Sandbox records are separate from blockchain transactions. Simulated records are not on-chain.')+'</p>'+live.join(''));}
  function chainSheet(){const mints=state.tokenMints;openSheet(t('Monad 测试网验证','Monad Testnet verification'),'<p class="muted small">'+t('这里展示实际铸币记录；仅授权样例 A 凭证符合现有规则，随机模拟夜晚不能参与。测试代币无经济价值。','Actual mint records are shown here. Only shared sample A qualifies; random nights do not. Test tokens have no economic value.')+'</p><div class="receipt-id">'+esc(state.tokenPolicy.contractAddress||t('未配置合约','Contract not configured'))+'</div>'+mints.map(m=>'<div class="entry"><div><strong>'+money(m.points)+' SLEEP</strong><small>'+t(m.status==='confirmed'?'已确认':'等待或需恢复',m.status==='confirmed'?'Confirmed':'Pending or needs recovery')+'</small></div>'+(m.status==='confirmed'&&/^0x[0-9a-f]{64}$/i.test(m.transactionHash||'')?'<a class="text-button" target="_blank" rel="noopener noreferrer" href="https://testnet.monadscan.com/tx/'+m.transactionHash+'">'+t('查看交易','View transaction')+'</a>':'')+'</div>').join('')+'<a class="secondary spaced" href="/?lang='+language+'#tokenize">'+t('打开现有测试网铸币入口','Open the existing testnet mint flow')+'</a><p class="fine-note">'+t('测试网铸币基于凭证，不扣减这里的积分或虚拟代币余额。','Testnet minting uses a receipt. It does not spend points or virtual tokens here.')+'</p>');}
  function goalSheet(){openSheet(t('睡眠目标','Sleep goal'),'<form id="goal-form"><label class="form-field" for="goal-minutes"><span>'+t('每晚目标时长','Target time asleep')+'</span><select id="goal-minutes">'+[360,390,420,450,480,510,540,570,600].map(n=>'<option value="'+n+'" '+(n===goalMinutes?'selected':'')+'>'+duration(n)+'</option>').join('')+'</select></label><p class="fine-note">'+t('保存在当前浏览器，用于目标展示，不改变积分计算。','Saved in this browser for your goal display. It does not change scoring.')+'</p><button class="primary" type="submit">'+t('保存目标','Save goal')+'</button></form>');}
  function updateQuotes(){if(!state)return;for(const kind of ['cash','token']){const input=$(kind+'-points'),button=$(kind+'-submit');if(!input||!button)continue;const p=kind==='cash'?state.cashPolicy:state.tokenExchangePolicy||{minimumPoints:1,maximumPoints:10000};const frozen=kind==='token'&&unresolvedToken;const n=frozen?frozen.points:Number(input.value),valid=!!frozen||Number.isInteger(n)&&n>=p.minimumPoints&&n<=p.maximumPoints&&n<=state.account.points;if(frozen)input.value=String(n);$(kind+'-estimate').textContent=kind==='cash'?yuan(valid?Math.floor(n*p.rateFenPer100Points/100):0):money(valid?n:0)+' SLEEP';$(kind+'-limit').textContent=t('最低 ','Minimum ')+p.minimumPoints+t(' 分，最多 ',' points, maximum ')+p.maximumPoints+t(' 分；当前可用 ',' points; available ')+money(state.account.points);const pending=kind==='cash'?state.cashRedemptions.some(r=>r.status==='integration_pending'):unresolvedToken;button.disabled=busy||(kind==='cash'&&pending)||(!valid&&!(kind==='token'&&pending));input.disabled=busy||(kind==='token'&&!!pending);document.querySelectorAll('[data-preset="'+kind+'"]').forEach(b=>{b.disabled=busy||(kind==='token'&&!!pending);});if(frozen)$(kind+'-limit').textContent=t('恢复原兑换：','Resume original exchange: ')+money(n)+t(' 积分，不创建另一笔扣款。',' points. No additional charge is created.');}}
  async function mutate(kind,id){if(busy||!state)return;if(kind==='claim'&&received())return;if(kind==='order'&&unresolvedOrder&&unresolvedOrder.productId!==id){toast(t('请先确认上一笔兑换','Resolve your pending redemption first'));return;}if(kind==='order'&&!unresolvedOrder)savePendingOrder({accountId,productId:id,requestId:crypto.randomUUID()});const requestId=kind==='order'?unresolvedOrder.requestId:null;busy=true;updateBusy();try{state=await api(kind==='claim'?'/api/demo/claims':'/api/demo/orders',kind==='claim'?(simulationId?{profile:'simulation',simulationId}:{profile:'screenshot'}):{productId:id,requestId});lastSynced=new Date().toISOString();connection(true);errorBanner('');render();if(kind==='claim')toast(t('已领取 ','Claimed ')+money(received().awardedPoints)+t(' 积分',' points'));else{const order=state.orders.find(o=>o.id===requestId);if(!order)throw new Error(t('兑换结果待确认','Redemption result is pending'));savePendingOrder(null);orderSheet(order,true);}}catch(e){let recovered=false;try{state=await api(stateURL());connection(true);errorBanner('');render();const order=state.orders.find(o=>o.id===requestId);if(kind==='order'&&order){savePendingOrder(null);orderSheet(order,true);recovered=true;}else if(kind==='order'&&e.status>=400&&e.status<500)savePendingOrder(null);if(kind==='claim'&&received()){toast(t('本晚积分已入账','This sleep reward is in your account'));recovered=true;}}catch{connection(false);errorBanner(t('结果尚待确认，请刷新核对记录后再操作。','Result pending. Refresh to check records before continuing.'));}if(!recovered){toast(errorMessage(e));reconcilePending();if(kind==='order'&&$('sheet').open)redeemSheet(id);}}finally{busy=false;updateBusy();updateQuotes();}}
  async function exchangeToken(){if(busy)return;const points=unresolvedToken?.points??Number($('token-points').value);if(!unresolvedToken)savePendingToken({accountId,points,requestId:crypto.randomUUID()});const pending=unresolvedToken;busy=true;updateBusy();updateQuotes();let success=false;try{state=await api('/api/demo/token-exchanges',{points,requestId:pending.requestId});success=state.tokenExchanges.some(r=>r.id===pending.requestId);if(!success)throw new Error(t('兑换结果待确认','Exchange result pending'));}catch(e){try{state=await api(stateURL());success=state.tokenExchanges.some(r=>r.id===pending.requestId);if(!success&&e.status>=400&&e.status<500)savePendingToken(null);}catch{connection(false);errorBanner(t('兑换结果待确认，请恢复同一笔请求。','Exchange result pending. Resume the same request.'));}if(!success)toast(errorMessage(e));}finally{if(success){savePendingToken(null);connection(true);errorBanner('');toast(t('虚拟代币已入账：','Virtual tokens received: ')+money(points)+' SLEEP');}busy=false;lastSynced=new Date().toISOString();render();reconcilePending();}}
  async function cashRequest(cancelId){if(busy)return;const points=Number($('cash-points')?.value);busy=true;updateBusy();updateQuotes();try{state=await api(cancelId?'/api/demo/cash-redemptions/cancel':'/api/demo/cash-redemptions',cancelId?{requestId:cancelId}:{points});connection(true);errorBanner('');toast(cancelId?t('申请已取消，积分未变动','Request cancelled. Points unchanged.'):t('申请已保存，等待通道接入；尚未打款','Request saved. Integration pending; no money sent.'));}catch(e){try{state=await api(stateURL());connection(true);}catch{connection(false);}toast(errorMessage(e));}finally{busy=false;lastSynced=new Date().toISOString();render();}}
  document.addEventListener('click',event=>{const el=event.target.closest('button,a');if(!el)return;if(el.dataset.route){go(el.dataset.route);return;}if(el.dataset.rewardRoute){rewardsView=el.dataset.rewardRoute;go('rewards');return;}if(el.dataset.rewards){rewardsView=el.dataset.rewards;render();return;}if(el.dataset.product){redeemSheet(el.dataset.product);return;}if(el.dataset.order){const o=state.orders.find(o=>o.id===el.dataset.order);if(o)orderSheet(o);return;}if(el.dataset.night){refresh(el.dataset.night==='sample-a'?null:el.dataset.night);return;}if(el.dataset.cancelCash){cashRequest(el.dataset.cancelCash);return;}if(el.dataset.preset){if(busy||el.dataset.preset==='token'&&unresolvedToken)return;const kind=el.dataset.preset,p=kind==='cash'?state.cashPolicy:state.tokenExchangePolicy;$(kind+'-points').value=el.dataset.value==='all'?Math.min(state.account.points,p.maximumPoints):el.dataset.value;updateQuotes();return;}if(el.id==='claim'){mutate('claim');return;}if(el.dataset.submit==='order'){mutate('order',el.dataset.id);return;}const action=el.dataset.action;if(action==='close')$('sheet').close();if(action==='random')refresh(crypto.randomUUID());if(action==='sample-a')refresh(null);if(action==='ledger')ledger();if(action==='goal')goalSheet();if(action==='receipts')receipts();if(action==='chain')chainSheet();if(action==='orders'){rewardsView='orders';go('rewards');}if(action==='language')location.href='/app?lang='+(language==='en'?'zh':'en')+location.hash;if(action==='source')openSheet(t('设备与数据来源','Device & data source'),'<div class="detail-row"><span>'+t('当前数据','Current data')+'</span><strong>'+t(synthetic()?'虚拟人物与模拟夜晚':'授权公开单夜样例 A',synthetic()?'Fictional person & simulated night':'Shared single-night sample A')+'</strong></div><div class="detail-row"><span>'+t('设备连接','Device connection')+'</span><strong>'+t('未连接','Not connected')+'</strong></div><p class="fine-note">'+t('网页不会读取或上传你的健康数据。Apple Health 读取需要原生 iOS App；这里的随机记录仅用于体验。','This web app does not read or upload your health data. Apple Health requires the native iOS app. Random records here are for demonstration.')+'</p>');if(action==='privacy')openSheet(t('账户与隐私','Account & privacy'),'<p class="muted small">'+t('当前是匿名体验账户。积分与兑换保存在服务端，并与官网共用。清除浏览器数据后不能自动恢复；模拟人物并非真实用户。','This anonymous demo account is shared with the website. Points and redemptions are stored on the server. Clearing browser data removes automatic access. Fictional people are not real users.')+'</p><div class="receipt-id">'+esc(accountId)+'</div><button class="secondary" data-action="copy-account">'+icon('copy')+t('复制账户编号','Copy account ID')+'</button>');if(action==='copy-account'){if(navigator.clipboard?.writeText)navigator.clipboard.writeText(accountId).then(()=>toast(t('账户编号已复制','Account ID copied'))).catch(()=>toast(t('请长按编号复制','Select the ID to copy')));else toast(t('请长按编号复制','Select the ID to copy'));}if(action==='restart')openSheet(t('开始一次新体验？','Start a fresh experience?'),'<p class="muted small">'+t('将切换到新的匿名账户，旧积分与记录不会删除，但不再显示。官网也会切换账户。','Switches to a new anonymous account in the app and website. Existing server records are retained but will no longer appear here.')+'</p><button class="primary" data-action="confirm-restart">'+t('确认，开始新体验','Start fresh')+'</button>');if(action==='confirm-restart'&&!busy){savePendingOrder(null);savePendingToken(null);accountId=crypto.randomUUID();simulationId=null;save('sleepDemoAccount',accountId);save('momoSimulationId',null);state=null;$('sheet').close();location.hash='today';$('content').innerHTML='<div class="loading"><span class="spinner"></span></div>';refresh();}});
  document.addEventListener('input',event=>{if(['cash-points','token-points'].includes(event.target.id))updateQuotes();});
  document.addEventListener('submit',event=>{if(['cash-form','token-form','goal-form'].includes(event.target.id))event.preventDefault();if(event.target.id==='cash-form'){if(!$('cash-submit').disabled)cashRequest();return;}if(event.target.id==='token-form'){if(!$('token-submit').disabled)exchangeToken();return;}if(event.target.id==='goal-form'){const n=Number($('goal-minutes').value);if(!Number.isInteger(n)||n<360||n>600)return;goalMinutes=n;save('momoSleepGoal',String(n));$('sheet').close();render();toast(t('睡眠目标已更新','Sleep goal updated'));}});
  window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0,behavior:'instant'});$('content').querySelector('h1')?.focus({preventScroll:true});});
  window.addEventListener('online',()=>{if(!busy)refresh();});
  $('refresh').onclick=()=>refresh();
  refresh().then(()=>{if(!storage)toast(t('浏览器无法保存账户，离开后可能丢失访问。','Browser storage is unavailable. Access may be lost after leaving.'));});
})
`;
